  const list = Object.keys(CORE); let i = 0;
  const work = async () => { while (i < list.length) { const u = list[i++];
    if (oc && om[u] === CORE[u]) { const r = await oc.match(u); if (r) { await c.put(u, r); continue; } }
    try { const r = await fetch(u, { cache: 'reload' }); if (r.ok) await c.put(u, r); } catch (er) {} } };
