const MUSIC_FRESH = ['assets/bgm/rain.m4a', 'assets/bgm/title.m4a'];
self.addEventListener('activate', e => { e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== VER && k !== MUSIC).map(k => caches.delete(k))))
  .then(() => caches.open(MUSIC)).then(c => Promise.all(MUSIC_FRESH.map(f => c.delete(new URL(f, self.registration.scope).href)))).then(() => self.clients.claim())); });
// 音楽（2026-11-24）: 版を上げても消えない別の箱（toh-music）に入れる。
// まだ入っていない曲は、ネットからそのまま流しながら（待たせない）、裏で丸ごと保存する
const MUSIC = 'toh-music-2';
